import{_ as a,C as e,c as o,o as i,j as r,G as s,b as t,a0 as n,a as l,w as d,a1 as u}from"./chunks/framework.DKRgXLPU.js";const c=JSON.parse('{"title":"Como montar sua rotina pré-injeção","description":"","frontmatter":{},"headers":[],"relativePath":"pt/education/mental-strength/pre-shot-routine.md","filePath":"pt/education/mental-strength/pre-shot-routine.md"}');const m=a({name:"pt/education/mental-strength/pre-shot-routine.md"},[["render",function(a,c,m,p,h,f){const b=e("AdBanner"),q=e("Mermaid"),v=e("AdInArticle");return i(),o("div",null,[c[1]||(c[1]=r("h1",{id:"como-montar-sua-rotina-pre-injecao",tabindex:"-1"},[l("Como montar sua rotina pré-injeção "),r("a",{class:"header-anchor",href:"#como-montar-sua-rotina-pre-injecao","aria-label":'Permalink to "Como montar sua rotina pré-injeção"'},"​")],-1)),s(b),c[2]||(c[2]=r("p",null,"Sua rotina pré-arremesso é uma das ferramentas mais poderosas do seu jogo mental. É uma sequência consistente de ações que prepara você para cada arremesso e ativa seu melhor estado de desempenho.",-1)),c[3]||(c[3]=r("div",{class:"tip custom-block"},[r("p",{class:"custom-block-title"},"A Grande Ideia"),r("p",null,[r("strong",null,"Sua rotina é a porta de entrada para o estado de fluxo."),l(' Uma rotina consistente antes da sessão de fotos sinaliza para o seu cérebro: "É hora de executar." Com a repetição, ela se torna um gatilho automático para o máximo desempenho.')])],-1)),(i(),t(u,null,{default:d(()=>[s(q,{id:"mermaid-13",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BComece%20a%20rotina%5D%20--%3E%20B%5BO%20c%C3%A9rebro%20reconhece%20padr%C3%B5es%5D%0A%20%20%20%20B%20--%3E%20C%5BMudan%C3%A7a%20autom%C3%A1tica%20de%20estado%5D%0A%20%20%20%20C%20--%3E%20D%5BModo%20de%20execu%C3%A7%C3%A3o%5D%0A%20%20%20%20D%20--%3E%20E%5BDesempenho%20m%C3%A1ximo%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20C%20fill%3A%23e8f5e9%0A%20%20%20%20style%20D%20fill%3A%23fff4e1%0A%20%20%20%20style%20E%20fill%3A%23fff4e1%0A"})]),fallback:d(()=>[...c[0]||(c[0]=[l(" Loading... ",-1)])]),_:1})),c[4]||(c[4]=n('<h2 id="por-que-as-rotinas-funcionam" tabindex="-1">Por que as rotinas funcionam <a class="header-anchor" href="#por-que-as-rotinas-funcionam" aria-label="Permalink to &quot;Por que as rotinas funcionam&quot;">​</a></h2><h3 id="a-consistencia-gera-confianca" tabindex="-1">A consistência gera confiança. <a class="header-anchor" href="#a-consistencia-gera-confianca" aria-label="Permalink to &quot;A consistência gera confiança.&quot;">​</a></h3><p>Ao fazer sempre a mesma coisa, você elimina as variáveis. Seu corpo sabe o que esperar. Isso cria uma sensação de controle e familiaridade, mesmo em situações desconhecidas.</p><h3 id="rotinas-desencadeiam-estados" tabindex="-1">Rotinas desencadeiam estados <a class="header-anchor" href="#rotinas-desencadeiam-estados" aria-label="Permalink to &quot;Rotinas desencadeiam estados&quot;">​</a></h3><p>Com a repetição, sua rotina se torna associada ao seu desempenho. Iniciar a rotina automaticamente desencadeia a mudança mental para o modo de execução.</p><h3 id="rotinas-bloqueiam-distracoes" tabindex="-1">Rotinas bloqueiam distrações <a class="header-anchor" href="#rotinas-bloqueiam-distracoes" aria-label="Permalink to &quot;Rotinas bloqueiam distrações&quot;">​</a></h3><p>Uma rotina dá à sua mente algo em que se concentrar. Não há espaço para se preocupar com a pontuação, o público ou o que pode acontecer.</p><h3 id="rotinas-controlam-a-excitacao" tabindex="-1">Rotinas Controlam a Excitação <a class="header-anchor" href="#rotinas-controlam-a-excitacao" aria-label="Permalink to &quot;Rotinas Controlam a Excitação&quot;">​</a></h3><p>Uma rotina bem planejada ajuda a regular seu nível de energia – acalmando você se estiver muito agitado e concentrando você se estiver sem energia.</p><h2 id="elementos-de-uma-rotina-eficaz" tabindex="-1">Elementos de uma rotina eficaz <a class="header-anchor" href="#elementos-de-uma-rotina-eficaz" aria-label="Permalink to &quot;Elementos de uma rotina eficaz&quot;">​</a></h2><h3 id="fase-1-avaliacao-fora-do-circulo" tabindex="-1">Fase 1: Avaliação (Fora do Círculo) <a class="header-anchor" href="#fase-1-avaliacao-fora-do-circulo" aria-label="Permalink to &quot;Fase 1: Avaliação (Fora do Círculo)&quot;">​</a></h3><p>Antes de agir, reúna informações:</p><ul><li>Analise o terreno (inclinações, obstáculos, superfície)</li><li>Avalie a situação (pontuação, posições das bolas)</li><li>Escolha seu alvo e local de pouso</li><li>Decida o tipo de arremesso (apontar, chutar, lançar, rolar)</li></ul><p><strong>É aqui que a reflexão acontece.</strong> Reserve um tempo para isso.</p><h3 id="fase-2-transicao-entrando-no-circulo" tabindex="-1">Fase 2: Transição (Entrando no Círculo) <a class="header-anchor" href="#fase-2-transicao-entrando-no-circulo" aria-label="Permalink to &quot;Fase 2: Transição (Entrando no Círculo)&quot;">​</a></h3><p>A transição do pensar para o agir:</p><ul><li>Ação física (entrar no círculo de forma consistente)</li><li>Sinal mental (uma palavra ou frase que indica o &quot;modo de execução&quot;)</li><li>Respiração (uma respiração consciente para se centrar)</li></ul><p><strong>Este é o interruptor.</strong> A análise termina aqui.</p><h3 id="fase-3-preparacao-no-circulo" tabindex="-1">Fase 3: Preparação (No Círculo) <a class="header-anchor" href="#fase-3-preparacao-no-circulo" aria-label="Permalink to &quot;Fase 3: Preparação (No Círculo)&quot;">​</a></h3><p>Prepare seu corpo:</p><ul><li>Postura consistente (sempre a mesma)</li><li>Teste de aderência (sinta a bola)</li><li>Alinhamento com o objetivo</li><li>Gatilho físico (um pequeno movimento seu)</li></ul><h3 id="fase-4-visualizacao-breve" tabindex="-1">Fase 4: Visualização (Breve) <a class="header-anchor" href="#fase-4-visualizacao-breve" aria-label="Permalink to &quot;Fase 4: Visualização (Breve)&quot;">​</a></h3><p>Veja o arremesso antes de fazê-lo:</p><ul><li>Imagine a trajetória da bola (2-3 segundos no máximo)</li><li>Sinta o arremesso bem-sucedido</li><li>Conecte-se visualmente com seu público-alvo.</li></ul><h3 id="fase-5-execucao" tabindex="-1">Fase 5: Execução <a class="header-anchor" href="#fase-5-execucao" aria-label="Permalink to &quot;Fase 5: Execução&quot;">​</a></h3><p>Faça o arremesso:</p><ul><li>Foco externo (apenas alvo)</li><li>Confie no seu corpo.</li><li>Liberte sem hesitação</li><li>Siga em frente naturalmente</li></ul>',27)),s(v),c[5]||(c[5]=n('<h2 id="construindo-sua-rotina-pessoal" tabindex="-1">Construindo sua rotina pessoal <a class="header-anchor" href="#construindo-sua-rotina-pessoal" aria-label="Permalink to &quot;Construindo sua rotina pessoal&quot;">​</a></h2><h3 id="passo-1-observe-o-que-voce-ja-faz" tabindex="-1">Passo 1: Observe o que você já faz <a class="header-anchor" href="#passo-1-observe-o-que-voce-ja-faz" aria-label="Permalink to &quot;Passo 1: Observe o que você já faz&quot;">​</a></h3><p>Você provavelmente já tem alguma rotina. Observação:</p><ul><li>O que você faz antes de bons arremessos?</li><li>O que lhe parece natural?</li><li>O que te ajuda a se concentrar?</li></ul><h3 id="passo-2-elabore-sua-rotina" tabindex="-1">Passo 2: Elabore sua rotina <a class="header-anchor" href="#passo-2-elabore-sua-rotina" aria-label="Permalink to &quot;Passo 2: Elabore sua rotina&quot;">​</a></h3><p>Crie uma sequência que inclua:</p><ul><li>[ ] Fase de avaliação</li><li>[ ] Momento de transição claro</li><li>[ ] Configuração física consistente</li><li>[ ] Breve visualização</li><li>[ ] Gatilho de execução</li></ul><h3 id="passo-3-anote" tabindex="-1">Passo 3: Anote <a class="header-anchor" href="#passo-3-anote" aria-label="Permalink to &quot;Passo 3: Anote&quot;">​</a></h3><p>Seja específico. Exemplo:</p><ol><li><strong>Avalie:</strong> Leia o terreno, escolha o local de pouso</li><li><strong>Transição:</strong> Entre no círculo com o pé esquerdo primeiro e diga &quot;confiança&quot;.</li><li><strong>Configuração:</strong> Pés afastados na largura dos ombros, verifique a pegada, alinhe os ombros.</li><li><strong>Visualize:</strong> Veja o caminho, sinta a libertação</li><li><strong>Executar:</strong> Olhos no alvo, arremessar</li></ol><h3 id="passo-4-pratique-religiosamente" tabindex="-1">Passo 4: Pratique religiosamente <a class="header-anchor" href="#passo-4-pratique-religiosamente" aria-label="Permalink to &quot;Passo 4: Pratique religiosamente&quot;">​</a></h3><p>Use sua rotina em TODOS os arremessos durante o treino:</p><ul><li>Lançamentos fáceis</li><li>Lançamentos difíceis</li><li>Quando você está cansado</li><li>Quando você está fresco</li></ul><p>A rotina precisa se tornar automática.</p><h3 id="etapa-5-aprimorar-ao-longo-do-tempo" tabindex="-1">Etapa 5: Aprimorar ao longo do tempo <a class="header-anchor" href="#etapa-5-aprimorar-ao-longo-do-tempo" aria-label="Permalink to &quot;Etapa 5: Aprimorar ao longo do tempo&quot;">​</a></h3><p>Sua rotina vai evoluir. Observe o que funciona e ajuste. Mas não a altere durante a competição — apenas entre os eventos.</p><h2 id="horario-de-rotina" tabindex="-1">Horário de rotina <a class="header-anchor" href="#horario-de-rotina" aria-label="Permalink to &quot;Horário de rotina&quot;">​</a></h2><p>Sua rotina deve levar uma quantidade consistente de tempo:</p><ul><li>Muito rápido: Você está com pressa, sem a devida preparação.</li><li>Muito lento: você está pensando demais e perdendo o ritmo.</li><li>Na medida certa: tempo suficiente para se preparar, mas não tanto a ponto de você pensar demais.</li></ul><p><strong>Horário típico:</strong></p><ul><li>Avaliação: 5 a 10 segundos</li><li>Transição + Preparação: 3-5 segundos</li><li>Visualização + Execução: 3-5 segundos</li><li><strong>Total: 10-20 segundos</strong></li></ul><h2 id="erros-comuns-na-rotina" tabindex="-1">Erros comuns na rotina <a class="header-anchor" href="#erros-comuns-na-rotina" aria-label="Permalink to &quot;Erros comuns na rotina&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Erro</th><th>Problema</th><th>Solução</th></tr></thead><tbody><tr><td>Pular corda na prática</td><td>A rotina não é automática.</td><td>Use-o em todos os arremessos.</td></tr><tr><td>Muito complicado</td><td>Difícil de lembrar sob pressão.</td><td>Simplifique ao essencial</td></tr><tr><td>Pensar durante a execução</td><td>Interrompe o desempenho automático</td><td>Ponto de transição claro</td></tr><tr><td>Horários inconsistentes</td><td>Cria incerteza</td><td>Pratique em ritmo constante</td></tr><tr><td>Mudança no meio da competição</td><td>Introduz dúvidas</td><td>Apegue-se ao que você conhece.</td></tr></tbody></table><h2 id="solucao-de-problemas-de-rotina" tabindex="-1">Solução de problemas de rotina <a class="header-anchor" href="#solucao-de-problemas-de-rotina" aria-label="Permalink to &quot;Solução de problemas de rotina&quot;">​</a></h2><p><strong>Se você estiver com pressa:</strong></p><ul><li>Adicione uma pausa na transição.</li><li>Diminua a velocidade dos seus movimentos de preparação.</li><li>Faça uma pausa antes da visualização.</li></ul><p><strong>Se você está pensando demais:</strong></p><ul><li>Encurte a rotina</li><li>Use uma deixa de transição mais forte.</li><li>Foque mais no exterior</li></ul><p><strong>Se você for inconsistente:</strong></p><ul><li>Grave um vídeo de si mesmo para verificar.</li><li>Pratique a rotina sem arremessar</li><li>Obtenha feedback de um parceiro</li></ul><h2 id="rotinas-de-exemplo" tabindex="-1">Rotinas de exemplo <a class="header-anchor" href="#rotinas-de-exemplo" aria-label="Permalink to &quot;Rotinas de exemplo&quot;">​</a></h2><h3 id="rotina-simples" tabindex="-1">Rotina simples <a class="header-anchor" href="#rotina-simples" aria-label="Permalink to &quot;Rotina simples&quot;">​</a></h3><ol><li>Selecione o alvo</li><li>Entre, respire.</li><li>Segure firme, alinhe</li><li>Veja, jogue fora</li></ol><h3 id="rotina-detalhada" tabindex="-1">Rotina detalhada <a class="header-anchor" href="#rotina-detalhada" aria-label="Permalink to &quot;Rotina detalhada&quot;">​</a></h3><ol><li>Leia o terreno, escolha o local de pouso</li><li>Dê o primeiro passo com o pé esquerdo.</li><li>Diga &quot;suave&quot; mentalmente</li><li>Uma respiração, ombros relaxam</li><li>Pés posicionados, verificação de aderência</li><li>Alinhe os ombros ao alvo.</li><li>Veja o caminho (2 segundos)</li><li>Olhos fixos no alvo</li><li>Lançar</li></ol><h2 id="ponto-chave" tabindex="-1">Ponto-chave <a class="header-anchor" href="#ponto-chave" aria-label="Permalink to &quot;Ponto-chave&quot;">​</a></h2><blockquote><p>Sua rotina é sua âncora. No caos, ela é sua constante.</p></blockquote><p>Construa com cuidado. Pratique sempre. Confie plenamente.</p>',38)),s(b)])}]]);export{c as __pageData,m as default};
